SELECT r.display_name,r.canonical_remote,l.root_path,l.current_branch,l.head_sha,l.is_dirty FROM repositories r JOIN repository_locations l ON l.repository_id=r.id JOIN projects p ON p.id=r.project_id WHERE ($1::text IS NULL OR p.slug=$1) AND ($2::boolean IS NULL OR l.is_dirty=$2) AND l.is_present AND EXISTS (SELECT 1 FROM unnest($3::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path) ORDER BY r.display_name,l.root_path
